\label{lncurvgrowth}


For $t'\le t''$,
\[
L(t'')\le L(t')e^{C_2(t''-t')},
\qquad
\Theta(t'')+L(t'')\le(\Theta(t')+L(t'))e^{(C_1+C_2)(t''-t')}.
\]
In particular,
$\Theta(t'')\le(\Theta(t')+L(t'))e^{(C_1+C_2)(t''-t')}$.
\end{corollary}
\begin{proof}
\uses{lem:curve-shrinking-length-curvature-growth}
\sketch Apply Gronwall first to $L$ and then to $L+\Theta$.
\end{proof}

